    if (!guardado) { std::cout << "Error al abrir salida"; return 1; }
    guardado << texto_salida;
    if (!guardado) { std::cout << "Error al escribir salida"; return 1; }
    guardado.close();
    if (!guardado) { std::cout << "Error al cerrar salida"; return 1; }

    Conjunto recuperado{};
