            || comprobacion.bad()) {
            std::cout << "Error al releer salida";
            return 1;
        }
    }
    int aceptados{0};
    int rechazados{0};
    for (const Grupo& grupo : actual.grupos) {
        for (const Registro& registro : grupo.registros) {
            aceptados += registro.recuento.aceptados;
            rechazados += registro.recuento.rechazados;
        }
    }
    bool verificado = mismos_datos(actual, recuperado);
    std::cout << "Entrada aceptada\nGrupos: " << actual.grupos.size()
              << "\nAceptados: " << aceptados
              << "\nRechazados: " << rechazados
              << "\nVerificacion: " << verificado << "\n";
    if (!verificado) { return 1; }
    return 0;
}

